// Applied rules: [III④, C3, II_vec]
// Skipped rules: [III③: hit [10] is `fread`, which is not covered by the card's supported memory/string replacement templates; hit [11] `strchr` is subsumed by the III④ bounded delimiter-scan rewrite; II_vec: hit [9] on the fread/capacity-growth loop is abstained because its trip count depends on `fread` results and realloc growth]
#[inline]
pub unsafe fn choices_fread(
    mut c: *mut choices_t,
    mut file: *mut FILE,
    mut input_delimiter: c_char,
) {
    let mut buffer_size: size_t = (*c).buffer_size;
    let buffer_start: size_t = buffer_size;
    let mut capacity: size_t = INITIAL_BUFFER_CAPACITY as size_t;
    while capacity <= buffer_size {
        capacity = capacity.wrapping_mul(2 as size_t);
    }

    let mut buffer = safe_realloc((*c).buffer as *mut c_void, capacity) as *mut c_char;
    (*c).buffer = buffer;

    loop {
        let bytes_read = fread(
            buffer.offset(buffer_size as isize) as *mut c_void,
            1 as size_t,
            capacity.wrapping_sub(buffer_size),
            file,
        );
        buffer_size = (buffer_size as c_ulong).wrapping_add(bytes_read) as size_t as size_t;
        (*c).buffer_size = buffer_size;
        if !(buffer_size == capacity) {
            break;
        }
        capacity = capacity.wrapping_mul(2 as size_t);
        buffer = safe_realloc(buffer as *mut c_void, capacity) as *mut c_char;
        (*c).buffer = buffer;
    }

    buffer = safe_realloc(
        buffer as *mut c_void,
        buffer_size.wrapping_add(1 as size_t),
    ) as *mut c_char;
    (*c).buffer = buffer;

    let nul_pos = buffer_size;
    buffer_size = buffer_size.wrapping_add(1);
    (*c).buffer_size = buffer_size;
    *buffer.offset(nul_pos as isize) = '\0' as i32 as c_char;

    let scan_len = buffer_size.wrapping_sub(buffer_start);
    // SAFETY: `buffer` is the freshly (re)allocated `(*c).buffer`, non-null per allocator
    // contract, and valid for `buffer_size` bytes. The scan region starts at `buffer_start`
    // and has stable length `scan_len <= buffer_size` in this region. No Rust references to
    // the same memory are live across this mutable slice creation.
    let scan = unsafe {
        core::slice::from_raw_parts_mut(buffer.offset(buffer_start as isize), scan_len)
    };

    let delimiter = input_delimiter as u8;
    let mut line_start: usize = 0;
    let mut i: usize = 0;
    while i < scan.len() {
        if scan[i] as u8 == delimiter {
            scan[i] = '\0' as i32 as c_char;
            if line_start != i {
                choices_add(c, scan.as_mut_ptr().add(line_start));
            }
            line_start = i.wrapping_add(1);
        }
        i = i.wrapping_add(1);
    }
}

